const BlindPairing = require('blind-pairing')
const crypto = require('hypercore-crypto')
const b4a = require('b4a')
const z32 = require('z32')

module.exports = device_pairing
module.exports.verification_digits = verification_digits

// pairs a new device with an invite code. the new device shows 6 digits, the user types them
// on the device that made the invite, only then the new device is added and gets the keys
function device_pairing ({ swarm }) {
  const state = { pairing: new BlindPairing(swarm), member: null, candidate: null }
  const api = { invite, join, close }
  return api

  // device that already has the settings. on_request({ name }) returns the digits the user typed (or null to deny)
  function invite ({ settings, on_request }) {
    const { invite: code, publicKey } = BlindPairing.createInvite(settings.key)
    const paired = new Promise(wait_for_device)
    return { code: z32.encode(code), paired }
    function wait_for_device (resolve, reject) {
      state.member = state.pairing.addMember({ discoveryKey: settings.discovery_key, onadd: request => handle_request({ request, public_key: publicKey, settings, on_request }).then(resolve, reject) })
    }
  }

  // new device: sends its writer key and name, resolves with the keys to open the settings
  function join ({ code, writer_key, name, on_digits }) {
    on_digits(verification_digits(writer_key))
    return new Promise(wait_for_keys)
    function wait_for_keys (resolve, reject) {
      const user_data = b4a.concat([writer_key, b4a.from(name)])
      state.candidate = state.pairing.addCandidate({ invite: z32.decode(code), userData: user_data, onadd: result => resolve({ key: result.key, encryption_key: result.encryptionKey }) })
      state.candidate.request.on('rejected', err => reject(new Error('pairing denied: ' + err.message)))
    }
  }

  async function close () { await state.pairing.close() }
}

/***************************************
HANDLE REQUEST
***************************************/
async function handle_request ({ request, public_key, settings, on_request }) {
  request.open(public_key)
  const writer_key = request.userData.subarray(0, 32)
  const name = b4a.toString(request.userData.subarray(32))
  const typed = await on_request({ name })
  if (typed?.toUpperCase() !== verification_digits(writer_key)) {
    request.deny()
    throw new Error('the digits did not match, pairing denied')
  }
  await settings.add_device(writer_key, name)
  request.confirm({ key: settings.key, encryptionKey: settings.encryption_key })
  return { writer_key, name }
}

// same as p2p-news-app: last 6 hex chars of the discovery key of the writer key
function verification_digits (writer_key) {
  return b4a.toString(crypto.discoveryKey(writer_key), 'hex').slice(-6).toUpperCase()
}
